formulas.expression:
IF(
  FIND("/", {!fxNoWww}) > 0,
  LEFT({!fxNoWww}, FIND("/", {!fxNoWww}) - 1),
  IF(
    FIND("?", {!fxNoWww}) > 0,
    LEFT({!fxNoWww}, FIND("?", {!fxNoWww}) - 1),
    {!fxNoWww}
  )
)

IF(
  {!varTargetQueueName} = "NIQ_Routing_Exception",
  "No SLA: routing exception - RevOps triage, not seller response",
  IF(
    ISBLANK({!varSegment}),
    "No SLA: segment not resolved",
    "No SLA: no response hours configured for segment " & {!varSegment}
  )
)

LEFT(
  "Rejected under Sales Acceptance Policy " & {!getDecisionPolicy.Policy_Version__c}
  & ": " & TEXT({!$Record.Sales_Rejection_Reason__c})
  & "; declined by the accountable individual owner",
  255
)

LEFT(
  "Seller decision commitment under Sales Acceptance Policy " & {!getDecisionPolicy.Policy_Version__c}
  & ": decision due within " & TEXT(ROUND({!getDecisionPolicy.Acceptance_SLA_Hours__c}, 0))
  & " business hours of MQL entry (weekend-aware approximation)",
  255
)
